INSERT INTO tmp_seg_2022 (n, t2, t4, s1, s2, ejecutada, avance, logros, limites, observacion, acciones) VALUES
(1, '0', '1', 0.00, 1.00, 1.00, 100.00, '1.Consolidación del equipo de trabajo\n2. Planeación de la fase diagnostica \n3. Consolidación de Cotizaciones para realización de pruebas.', '', '', ''),
(2, '3', '12', 3.00, 12.00, 15.00, 107.14, 'Para el semestre 2022 II, se ha logrado realizar las actividades planificadas y acordadas buscando así fortalecer los valores y la integración de una o más cultura, buscando la rechazar la jerarquización y fomentando las relaciones entre los individuos. Entra estas actividades encontramos la Francofonia, expodeutchland, Clubes conversacionales ORII (3 clubes conversacionales básico) (1 club conversacional intermedio) , Tandem Virtuales con la universidad Hamdem de Alemania, Actividades KOIKA, Celebración Hangeul Nal AEKO, Visita de la Unión Europea, Actividades con la embajada de la India, Visita de la agregada de educación de Canadá y trabajos colectivos para la realización de tandem Francés, Le cinemá francophne, éducatión et sport, parler de sa famile. De acuerdo al seguimiento de las facultades las participantes fueron: CLUBES CONVERSACIONALES, éducatión et sport, parler de sa famile: Facultad de Ciencias economicas 2, Ingeneria 4, Facultad de educación 2, Facultad de Ciencias Basicás 2, Facultad de Ciencias Humanas 3, Visita de la agregada de educación: Facultad de educación programa Lic en inglés y Frances, y los demas actividades impactaron a todas las afacultades \n2 actividades fueron dirigidas a todas las facultades, 1 fue para facultad Bellas Artes', '', '', 'Incentivar a los estudiantes y a los diferentes programas pertenecientes a la Universidad del Atlantico, a la asitencia de eventos tantos virtual como presencial para que conozcan y vivan las diferentes actividades del programa de Multilingüismo e Interculturalidad'),
(3, '364', '117', 364.00, 117.00, 481.00, 96.20, 'Fortalecimiento de una segunda lenguas para los estudiantes de la Universidad del Atlantico a traves de los cinco niveles dictado por docentes y estudiantes del programa de Inmsersión y de los ultimos semestre de la Licenciatura de Lenguas Extranjeras. De acuerdo a lo anterio lograron culminar los cursos de ingles requeridos: 30 de la Facultad de Arquitectura, 6 Facultad de la de Bellas Artes, 34 de la Facultad de Ciencias Basicas, 92 de la Facultad de Ciencias Economicas, 25 de de la Facultad Ciencias Básicas, 30 de de la Facultad Ciencias Juridicas, 87 de Facultad, Ingenieria, 6 de la Facultad Nutrición y Dietetica y 54 de la Facultad Quimica Y Farmacia en el periodo 2022-1. Para el 2022-2 la participación fue la siguiente: 17 de la Fac. de Arquitectura, 7 de la Fac. de Bellas Artes, 5 de la Fac. de C. Básicas, 21 de la Fac. C. Económicas, 3 de la Fac. de C. Humanas, 5 de la Fac. de C. Jurídicas, 24 de la Fac. de Ingenierías, 14 de la Fac. de Nutrición y 21 de la Fac. de Quimica y Farmacia.', '', '', ''),
(4, '29', '0', 29.00, 0.00, 29.00, 103.57, '29 estudiantes de últimos semestres del Programa de Licenciatura de Lenguas Extranjeras de la Universidad del Atlántico viajaron a Canadá, tras resultar beneficiados para la realización del curso: English Language Educators Program en Dalhousie University en la ciudad de Halifax, Provincia de Nueva Escocia, una iniciativa que se se adelantó, con el apoyo de la embajada en Colombia, para contribuir al perfeccionamiento del idioma inglés de los jóvenes miembros de la comunidad educativa.', 'Los estudiantes participaron de un proceso de selección mediante convocatoria abierta en el que, basado en méritos académicos, fueron seleccionados aquellos con mayores puntajes. Una vez los jóvenes hayan culminado las clases, regresarán a compartir lo aprendido al dictar cursos del idioma inglés a estudiantes de pregrado de la Uniatlántico.', '', 'Para el año 2023, buscamos no solamente seguir impulsando a los medios de comunicaciones de la Universidad del Atlantico, si no tambien bucar alternativas paises donde no se ha realizado el programa de inmersión con los diferentes convenios para garantizar a los estudiantes de Lenguas extranjeras el fortalecimiento de se segundo idioma si no que tambien conozcan la cultura de otros paises'),
(5, '1', '0', 1.00, 0.00, 1.00, 7.14, 'Un estudiante entrante a la Facultad de Educación', 'Factores que impactan las movilidades es la falta de apoyos económicos que puedan ayudar al sosteniemiento de los estudiantes durante su proceso de movilidad.', 'La universidad logró participar en las convocatorias muevete por la costa y la convocatoria Tuna Guajira', 'Promover a traves de convocatorias Becas y Medias Becas nacionales a los estudiantes de las otras instituciones de Educación Superior (IES), para el fortalecimientos de las movilidades estudiantes nacionales hacia nuestra institución.'),
(6, '15', '70', 15.00, 70.00, 85.00, 653.85, 'En el 2022-1, se registraron 15 Estudiantes del Programa de Nutrición y Dietética y para el 2022-2, se registran 32 movilidades para Nutrición y Dietetica, 1 de la fac. de C. Básicas, 6 de la Fac. de C. Humanas, 17 de la fac. de Educación y 14 de la Fc. de Quimica y Farmacia.', 'Falta de apoyos económicos que puedan ayudar al sosteniemiento de los estudiantes durante su proceso de movilidad.', '', 'Seguir fortaleciendo la participacion de nuestros estudiantes en programas de movilidad que ayuden a incentivar los procesos de intercambios a traves de redes de Cooperación.'),
(7, '7', '10', 7.00, 10.00, 17.00, 130.77, 'En el 2022-1, los estudiantes extranjeros entrantes a la Universidad del Atlantico coresponden a: 1 de Facultad Ingenieria, 2 en posgrado(maestria Gestión Energetica), 1 facultad de Bellas Artes, 1 Facultad de Ciencia Humana, 2 Facultad Nutricion y Dietetica. Para el periodo 2022-2 se registra la movilidad de 3 estudiantes de la Fac. de Arquitectura, 3 de C. Juridicas, 2 de C. de la Educación, 4 de Ingeniería y 2 de Nutrición y Dietética.', 'Cancelaciones de estudiantes que ya tenian su proceso adelantado, por motivos personales y el inicio de la reactivacion de estos luego del covid-19.', '', 'Seguir fortaleciendo la participacion de nuestros estudiantes en programas de movilidad que ayuden a incentivar los procesos de intercambios a traves de redes de Cooperación.'),
(8, '31', '11', 31.00, 11.00, 42.00, 113.51, 'Se logró gracias al programa Inmersion de Lenguas extrajeras movilizar 29 estudiantes, y 2 estudiantes a traves del programa PILA VIRTUAL, en intermcabio académico; 32 estudiantes Fac. de Educación, 3 Fac. Humanas, 3 de la Fc. De C. Júridicas, 2 de C. Económicas y 2 de C. Básicas.', '', '', ''),
(9, '0', '38', 0.00, 38.00, 38.00, 172.73, '38 docentes con movilidad saliente internacional: 4 Facultad Bellas Artes, 3 Facultad Ciencias Económicas, 9 Ciencias Juridicas, 4 de la Facultad Ciencias Humanas, 5 de Fac. de Ingeniería, 12 de la Fc. de Quimica y Farmacia , 1 de la Fac. De Educación', '', '', 'Continuar gestionando convoctarias donde se genere participacion activa de nuestros docentes.'),
(10, '12', '97', 12.00, 97.00, 109.00, 545.00, 'En el 2022-1, 12 docentes con movilidad saliente nacional:1 Fac. Ingenieria, 4 C. Basicas, 1 Facultad C. Económicas y 6 de Nutrición y Dietetica. En el 2022-2, 13 de la Fac. de Bellas Artes, 1 de C. Humanas, 63 de C. Juridicas, 3 de la Fac. de Educación, 8 de la Fac. de Ingeniería, 1 de la Fc. de Quimica y Farmacia y 8 nuevos de la Fac. de Nutrición y Dietética.', 'Retraso en la entrega de la información por parte de las Fcultades para lla respectiva validación de la información registradaa por la ORII', '', 'Creación de alianzas, participacion en convocatorias que sean aporvechas por docentes de la UA.'),
(11, '20', '26', 20.00, 26.00, 46.00, 230.00, 'En el 2022-1, Se pudo contar con diferentes docentes internacionales en congresos, seminarios, talleres, clases, reuniones, etc. de manera virtual. 1 de Quimica y Farmacia, 11 de educación, 5 de C. Basicas, 1 de Bellas Artes y 2 reportado por la ORII. En el 2022-2, se registran 3 de la Fc. de Ingeniería, 7 más de la Fac. de Educación, 4 de la Facultad de Júridicas, 6 de la Fac. de Humanas, 1 de Bellas artes y 5 adicionales de la Fac. de C. Básicas.', '', '', 'Creación de alianzas, participacion en convocatorias que sean aporvechas por docentes de la UA.'),
(12, '0', '1', 0.00, 1.00, 1.00, 100.00, 'Compilación de actividades en materia de internacionalización curricular', '', '', ''),
(13, '6.3%', '6%', 6.30, 6.00, 12.30, 123.00, 'En el 2022-1 el Desarrollo de clases espejo contó con la Participación de 3 programas de la Facultad de C. Económicas con 7 claes espejos, 1 programa de la Facultad de Bellas Artes, 9 clases espejos en 2 programas la Facultad de Educación. (6/48) 48 programas de pregrado', '', '', 'Fortalcer la convocatoria en facultades que no esten participando /se observa al final del segundo semestre que falto motivar otras facultades por lo que se necesita fortalecer el plan de medios de las clases espejo.'),
(14, NULL, '20%', NULL, 20.00, 20.00, 200.00, 'La participación de las Facultades en la realización de actividades extracurriculares con componente internacional como Bellas artes con los programas de Arte Dramático y Danza; Educación con los programas Lic. En lenguas extranjeras, Lic. Humanidades y Maestría en Neuropedagogia, Quimica y Farmacia con el programa de Farmacia, Ingeniería con el programa de Ing. Industrial; C. Económicas con el programa de admón de empresas turisticas, C. Básicas, con el programa de Biología, Fac. de Nutrición, con el programa de Nutrición y Dietética (10/48) 48 programas de pregrado', '', '', 'Seguir con la metodologia actual de apoyo a varios programas. El apoyo en el plan de medios, la reserva de salones (virtuales y presenciales) y la elaboracion de libretos son fundamentales'),
(15, '0', '1', 0.00, 1.00, 1.00, 100.00, 'Existe 2 propuestas para esta proyección, una trabajada por el PEV y la Vicerrectoría de Docencia y otra trabajada desde Planeación y Rectoría', '', '', ''),
(16, NULL, '10', NULL, 10.00, 10.00, 100.00, 'Se han identificado las siguientes practicas de innovación educativa,\nBellas Artes 2\nC. de la Educación: 5\nC. Humanas: 2\nC. Económicas: 1\nC. Jurídicas: 1\nC. Básicas: 3\nArquitectura: 2\nIngeniería: 1\nQuimica y Farmacia: 1\nNutrición:1', 'Se aplicó un instrumento de indagación entre los docentes , que permitió detectar experiencias que de manera autónoma venían desarrollándose y los docentes interesados en desarrollar este tipo de experiencias. Se realizó el primer encuentro de prácticas de innovación educativa que identificó 19 experiencias de las Facultades. Ver cuadro. Se premiaron 3 y se reconocieron 2 con menciones de honor.', '', 'Fortalecimiento de las relaciones entre el Co-Lab y la Universidad del Atlántico.'),
(17, NULL, '2', NULL, 2.00, 2.00, 100.00, 'Como recursos digitales habilitados para la docencia se identifican 27 entre tutoriales, videos y OVAS creados en el 2022 se evidencias en el micrositio\nhttps://evirtual.uniatlantico.edu.co/', '', '', 'Se adquirieron licencias de Nearpod (100) para trabajos en Docencia como presentaciones de temas, evaluiaciones y clases dinamicas y powton (5) para desarrollo de contenido. (herramientas de autor que nos permiten desarrollar otros recursos digitales).'),
(18, '80', '0', 80.00, 0.00, 80.00, 100.00, 'Para el soporte de las Asignatura virtuales de la Especialización en Gestión Fiscal y la Maestria en Desarrollo Urbano y Sostenible se crearon recursos digitales con la colaboración de docentes, los cuales estan alojados en la plataforma de SICVI y en SIGAP, sin embargo no pudieron ser subidas al repositorio de la Biblioteca.', '', 'Como adición a este indicador se ha trabajado con la Facultad de Ingenieria en una propuesta de asignatura virtual donde tambien se diseñaron recursos digitales con apoyo de docentes', ''),
(19, NULL, '20', NULL, 20.00, 20.00, 200.00, 'Actualmente se cuenta con 20 recursos digitales disonibles en el micrositio de https://evirtual.uniatlantico.edu.co/', '', 'Cómo enlazar una reunión de Google Meet a SICVI-567:\nhttps://www.youtube.com/watch?v=L_y1F8_TLpE\nCómo subir recursos a SICVI-567: https://www.youtube.com/watch?v=ITmJXQIblLM', ''),
(20, '1', NULL, 1.00, NULL, 1.00, 50.00, 'De acuerdo a la auditoría realizada en el 2022-1 a las Facultades del uso del sicvi, se pudo comprobar el funcionamiento de las capacidades de los servidores para mantener las plataformas habilitadas 24/7.', '', 'En el segundo semestre del 2022 y hasta septembre se conto con la licencia de Intelliboard, se manera la auditoria para el segundo semestre queda pendiente hasta tanto se reactive la licencia en el 2023-01', 'Se continua realizando la auditoria básica entregada por el sistema de gestion de aprendizaje Moodle'),
(21, '17%', '2%', 17.00, 2.00, 19.00, 31.67, 'De los 1417 docentes correspondientes al año 2022, se lograronn capacitar en competencias digitales 275 docentes , que corresponde al 19%', '', '', 'Se incrementó la oferta de curso sobre herramientas TIC para los docentes'),
(22, '0%', '0.69%', 0.00, 0.69, 0.69, 2.30, 'En el segundo semestre de 2022 se capacitaron un total de 205 estudiantes. \nEstuvo representado con la Facultad de Ciencias Juridicas con 30 - Quimica y Farmacia con 128 - Estudiantes de diferentes programas en la SEDE Sabanalarga con 47 estudiantes. https://docs.google.com/presentation/d/11v_25tvGNFPZ2NXPtfc_VamieyggEfJL/edit?usp=share_link&ouid=118429031234109183662&rtpof=true&sd=true', '', '', ''),
(23, '21', '28', 21.00, 28.00, 49.00, 245.00, 'A traves de la formulación del Plan de Formación por Facultad y de capacitaciones en alianza con Desarrollo Docente, se logro capacitar a 1044 usuarios', 'El desarrollo de cursos de formación (asistencia) puede disminuir al no llevarse a cabo de manera presencial.', 'Cada vez que sea contratado un recurso se prioriza la capacitación para el equipo de Bibliotecas.\nCuando el equipo se encuentra capacitado en el uso de nuevos recursos puede difundir el conocimiento a los demás usuarios de la Biblioteca.', 'Para los futuros periodos academicos del año 2023 se establecen Planes de Formación para facultades, docentes y equipo de bibliotecas, con el animo de incentivar mayor uso de la Biblioteca Digital'),
(24, '0', '1', 0.00, 1.00, 1.00, 33.33, 'Catedra Julio Enrique Blanco', '', '', ''),
(25, '0', '0', 0.00, 0.00, 0.00, 0.00, 'Formato de estudio previo y propuesta de consultoría o asesoría de investigación formulada por la Facultad de Ciencias Económicas.', 'No se aprobaron recursos desde el nivel central ni el Comité de Planeación prioriza recursos para la contratación de un estudio de pertinencia.', '', 'Se buscaran nuevas estrategias para el diseño y aprobación de un estudio de pertinencia de programas en las sedes regionales. Se están concretando reuniones con la Cámara de Comercio de Barranquilla.'),
(26, '75', '71', 75.00, 71.00, 677.00, 87.69, 'En el 2022-2 se graduaron 59 estudiantes de la Fac. de Arquitectura, 1 de la Fac. de Bellas artes, 5 de la Fac. de C. Básicas, 6 de la Fac. de Educación, 21 de la Fac. de Ingeniería, 54 de la Fac. de Nutrición y Dietética.', 'Algunos estudiantes no cumplian requisitos de grado y muchos realizaron solicitud de tránsito a programas profesionales universitarios por lo que necesitaban no tener la calidad de egresado para este trámite. El programa de Biotransformación no tuvo continuidad de cohortes semestrales, por lo que en la solicitud de renovación del programa se solicitó modificación del nombre del programa y la inclusión del tercer ciclo profesional universitario, la cual ya recibió visita de pares académicos y se está a la espera del aval del Ministerio de Educación Nacional.', '', 'Realizar un acompañamiento desde Bienestar Universitario y las coordinaciones de programa con el apoyo del Departamento de Regionalización, para la graduación de los estudiantes en las sedes regionales además de trabajar en el tránsito de estudiantes para un ciclo profesional universitario.'),
(27, '0', '1', 0.00, 1.00, 1.00, 100.00, 'Gracias a la alizana con el portal de empleo de la Universidad (elempleo.com), se han recopilado datos de los egresados que han sido contratados mediante la plataforma. Con el aporte de los estudios de impacto y seguimiento se recopilan datos de los egresados que se encuentran empleados y los que no.', 'Hasta el momento no ha sido posible construir la información con el nivel de detalle tal, que se conozcan los egresados empleados por cada una de las sedes de la Universidad del Atlántico. La información precisa de los perfiles para llevar a cabo el instrumento, asi como también lo macro que es el proceso de llevar a cabo la encuesta nos limita en llevar a cabo este informe de manera detallada y en un menor tiempo. El llevar a cabo y medir este inficador lleva más de un semestre, empezando desde la recopilación de datos , elaboración y validación del instrumento.', 'En primer lugar para el segundo semestre del año 2022, se logró consolidar las bases de datos de los graduados en Región, extraídas de información recopilada de bases de datos del DARA, luego se logró elaborar un instrumento para aplicarlo a estos graduados, posteriormente se cargó dicho instrumento en el sistema de encuestas ON LINE (SEO) para la aplicación de esta a los graduados. Sin embargo, apesar que no se ha terminado de aplicar este instrumento, de tal manera que se recoja esa información en específico y a detalle, Se logró construir un informe diagnóstico de la empleabilidad de los graduados en Región, como informe preliminar , con base a la información extraída del Observatorio Labotal para la Educación (OLE), herramienta del Ministerio de Educación Nacional, logrando hacer un análisis preliminar de algunos programas de los gradaudos de Región que reporta esta herramienta.', 'Identificar y caracterizar a los egresados por región (Sedes) para validar su estado actual y así construir un informe integral. Aplicar el instrumento totalmente a los gradaudos para lograr la caraterización a detalle y extraer gran información laboral de los graduados de todos los programas en Región.'),
(28, '1', '0', 1.00, 0.00, 1.00, 100.00, 'Esta electiva se invita a involucrarse en el aporte en el desarrollo de su entorno. Al final se cuenta con 1 Electiva en habitos y estilos de vida saludable por parte de la facultad de nutrición y Dietetica.', 'Se debe trabajar la interdisciplinariedad que se desea en esta electiva regional dado que puede perderse al trabajarla una sola Facultad.', '', 'Desde Regionalización se convocarán reuniones con los profesores de todas las Facultades con programas regionalizados para exponer la idea y desarrollar contenido. Se explorará involucrar otras Facultades y el programa de Virtualización para la participación de líderes comunitarios del área de influencia de las sedes regionales.'),
(29, '9', '13', 9.00, 13.00, 13.00, 144.44, 'Se continuó desde el Departamento de Regionalización haciendo énfasis en la importancia de docentes con altas dedicaciones y se lograron tener 9 docentes de tiempo completo ocasional en las Facultades con programas regionalizados, adicional se tuvieron 4 docentes de medio tiempo (3 ocasional y 1 pasante) con dedicación del 80% de dedicación. Estos fueron los docentes de tiempo completo para 2022-2: RADA SOLANO CARLOS ANTONIO; ORTEGA VIZCAINO EVERTH DE JESUS; SANTIAGO ESCAMILLA NAZIRA; VILLARREAL VILLA SANDRA MARGARITA; CERVANTES BARRAZA JONATHAN ALBERTO; MELENDEZ SERRANO ANGIE ISABEL; BALLESTA RODRIGUEZ INGRID; CELIS ROYET LEONARDO y CONSUEGRA ALGARIN MANUEL. Los docentes medio tiempo ocasional: FERNANDEZ ALVAREZ DIANA MARGARITA; BORJA POLO WILSON ENRIQUE; MARENCO VERGARA JUAN CARLOS; y ROMERO ATENCIO JONATHAN. Y el docente medio tiempo pasante: BORJA POLO WILSON ENRIQUE.', 'Hay docentes de tiempo completo y medio tiempo con asignación en región pero su dedicación a veces solo corresponden a actividad de clase.', '', 'Mantener el diálogo con decanos sobre la importancia de mantener docentes con altas dedicaciones en las sedes regionales para las actividades de docencia, investigación, extensión y proyección social.'),
(30, '0', '0', 0.00, 0.00, 0.00, 0.00, 'Durante el segundo semestre del 2022 se trabajó en la obtención de las Condiciones Institucionales de la sede regional Sur Suan desde la construcción de documentos para la solicitud hasta la visita de pares académicos del Ministerio de Educación, lo cual es necesario para los trámites de registros calificados de los programas en región.', 'Los trámites de registro calificado ante el Ministerio de Educación son bastante demorados, sin embargo la resolución de aprobación prodría llegar antes de finalizar el 2022.', '', 'Se puede propiciar reunión anticipatoria a la llegada de la resolución de aprobación del Ministerio con la Facultad de Ingeniería para apoyar en construcción de su resolución de transito al nuevo programa basados en las experiencias de los programas en región.'),
(31, '1248', '1229', 1248.00, 1229.00, 1238.50, 93.90, 'En el 2022-1 se tuvieron 1.248 estudiantes matriculados en las sedes regionales de la Universidad según reporte del Departamento de Admisiones (2022-05-13), con un total en la sede regional Sur Suan de 1.151, en la sede regional Centro Sabanalarga de 94 y en el CERES Sabanagrande de 3 estudiantes. Se detalla a continuación por Facultades: Arquitectura 234 en Suan y 24 en Sabanalarga, Ciencias Básicas 22 en Suan, Ciencias de la Educación 645 en Suan, 35 en Sabanalarga y 3 en Sabanagrande, Ingeniería 72 en Suan y 35 en Sabanalarga, y Nutrición y Dietética 178 en Suan. En el 2022-2 se tuvieron 1.229 estudiantes matriculados en las sedes regionales de la Universidad según reporte del Departamento de Admisiones (2022-12-8), con un total en la sede regional Sur Suan de 1.064; en la sede regional Centro Sabanalarga de 163 y en el CERES Sabanagrande de 2 estudiantes. Se detalla a continuación por Facultades: Arquitectura 234 en Suan y 24 en Sabanalarga, Ciencias Básicas 22 en Suan, Ciencias de la Educación 645 en Suan, 35 en Sabanalarga y 3 en Sabanagrande, Ingeniería 72 en Suan y 35 en Sabanalarga, y Nutrición y Dietética 178 en Suan.', 'Por directriz de Vicerrectoría de Docencia hubo una disminución de cupos para algunos programas de la Universidad. En la sedes regionales se tuvieron en cuenta dificultades de consecución de docentes específicos, inconvenientes de cruce de horarios, dificultades en uso de laboratorios que están en adecuaciones y previsión de sobreocupación de la sede en Suan.', '', 'Se esperan nuevas disposiciones del Gobierno Nacional con respecto al aumento de la cobertura en educación superior para el 2023 de la mano del fortalecimiento financiero de la Universidad para las sedes regionales.'),
(32, '0', '0', 0.00, 0.00, 0.00, 0.00, 'Se realizaron reuniones con la Facultad de Educación para plantear diseño de este programa. Se establecieron diálogos con la Secretaría de Educación Departamental sobre el mejoramiento de las competencias de Lectura crítica, Matemáticas, Sociales y Ciudadanas, Ciencias Naturales, e Inglés en los estudiantes de educación media.', 'Al ser una población a beneficiar de educación media es mejor realizarlo a través de convenios o proyectos con entidades territoriales o fundaciones.', '', 'Concretar el alcance del programa y la metodología de ejecución en los territorios.'),
(33, '4', '2', 4.00, 2.00, 6.00, 37.50, 'En el 2022, se lograron firmar 4 convenios, 1 por parte de la Facultad de Arquitectura y 3 por la Facultad de Ingeniería para apoyar la formación académica en región y las practicas académicas y profesionales. Durante el segundo semestre se firmaron 2 nuevos convenios para prácticas estudiantiles y otras actividades académicas, 1 por la Facultad de Ingeniería con Agrosavia y 1 por la Facultad de Nutrición y Dietética con la Alcaldía de Suan.', 'El trámite de firma de convenios al interior de la Universidd es largo', '', 'Desde el Departamento de Regionalización se prodrá brindar apoyo a las Facultades para optimizar la gestión realizada con entidades en la zona de influencia de las sedes regionales'),
(34, '119', '113', 119.00, 113.00, 113.00, 131.40, 'Se cierra el 2022 con 113 estudiantes vinculados a Semilleros de investigación, 28 de la Facultad de Arquitectura, 47 de la Facultad de Educación, 35 la Facultad de Nutrición y Dietética, 4 en la Facultad de Ciencias Básicas y 9 en la Facultad de Ingeniería. Durante el año participaron en actividades con la Red Institucional de Semilleros de Investigación de la Universidad del Atlántico (RedISIA). Desde los programas académicos regionalizados han venido realizando acciones para sostener y aumentar el número de estudiantes vinculados a Semilleros de Investigación, como la creación del nuevo grupo de investigación G-DIER para abordar problemáticas de la zona de influencia de las sedes regionales.', 'En algunos programas se cuentan con pocos docentes de tiempo completo que fomenten la realización de actividades de investigación en los estudiantes.', '', 'Preveer la graduación de estudiantes de Semillero de Investigación para desarrollar acciones de vinculación de nuevos estudiantes y que no se disminuya el semillero. Seguir de la mano con el Departamento de Investigaciones, las Facultades y programas regionalizados y la Gobernación del Atlántico para incentivar la vinculación de más estudiantes a los Semilleros existentes para lograr la meta de estudiantes con formación práctica en investigación .'),
(35, '36', '19', 36.00, 19.00, 55.00, 239.13, 'El 2022 cierra con 55 estudiantes desarrollando proyectos de innovación y/o emprendimiento distribuidos de la siguiente forma: 3 de la Facultad de Arquitectura, 2 de la Facultad de Ciencias Básicas, 7 de la Facultad de Ingeniería, 8 de la Facultad de Educación y 13 de la Facultad de Nutrición. Se destaca que muchos de los proyectos se han venido fortaleciendo durante el año y algunos se han presentado en eventos de socialización con la comunidad y de investigación. Durante el 2022-1 se logró una meta de 57 de los cuales algunos ya algunos estudiantes se graduaron.', 'Algunos estudiantes no cuentan con el tiempo suficiente para desarrollar proyectos de innovación y/o emprendimiento.', '', 'Seguir de la mano con el Departamento de Extensión, las Facultades y programas regionalizados y la Gobernación del Atlántico para incentivar la vinculación de más estudiantes a proyectos de innovación y/o emprendimiento.'),
(36, '0', '0', 0.00, 0.00, 0.00, 0.00, 'Se trabajó en una resolución para la creación de un Comité del Observatorio de Desarrollo Social en conjunto con la Vicerrectoría de Investigaciones, Extensión y Proyección Socal. También se han adelantado la organización de estadísticas de las sedes regionales y la creación de informes dinámicos para observar comportamientos en región.', 'No se cuenta con personal vinculado suficiente al Departamento de Regionalización con los perfiles requeridos para el diseño del observatorio de vida académica y universitaria en región.', '', 'Solicitar estudiantes en práctica en las Facultades a nivel de pregrado o estudiantes para desarrollar proyectos aplicados a nivel de especialización o maestría para cubrir el personal requerido para el diseño del Observatorio.'),
(37, '0', '0', 0.00, 0.00, 0.00, 0.00, 'Aprobación parcial del documento elaborado por parte de los Decanos y Vicerrector de Docencia', 'Tiempo disponible para la revisión del documento', 'El documento de la Politica se encuentra terminado, solo serevisa para complementar o corregir', 'Para el año 2023 agilizar y promover los espacios de revisión del documento para presentarlo lo antes posible al consejo superior'),
(38, '0', '0', 0.00, 0.00, 0.00, 0.00, 'Se realizo 2 reuniones con el \n Decano de Ciencias Humanas y docentes de lingüística de esta facultad', 'Poca disponibiidad \n del equipo de la\n Facultad de\n Ciencias Humanas', '', 'Se deja como compromiso una reunión con el consejo de facultad de ciencias humanas para la primera reunión de 2023'),
(39, '0', '4', 0.00, 4.00, 4.00, 400.00, 'Se estableció alianzas con las siguientes organizaciones:\n *Unidad de Victimas.\n *Mesa departamental de la Gobernación del Atlántico.\n *Mesa LGBTIQ+ de la Gobernación del Atlántico.\n *Defensoria del pueblo.', '', '', 'Realizar más alianzas o\n convenios en beneficio de los estudiantes de la Universidad del Atlántico'),
(40, '1', '1', 1.00, 1.00, 1.00, 100.00, 'Se ha logrado establecer a la Biblioteca digital como el centro de documentación de contenidos accesibles que cuentan con herramientas de audio para los usuarios con discapacidad\nvisual.', 'No se cuenta con equipos para edicion , ni video .', '', 'contar con los programas \n y equipos necesarios'),
